import React from 'react';
import type { FinishResults } from '../../../core/finishCalculations';

interface Props {
  results: FinishResults;
    hasMarble: boolean;
      electricalPts: number;
        plumbingPts: number;
          onElectricalChange: (value: number) => void;
            onPlumbingChange: (value: number) => void;
            }

            const cardStyle: React.CSSProperties = {
              background: '#fff',
                border: '1px solid #ddd',
                  borderRadius: 12,
                    overflow: 'hidden',
                      marginBottom: 12,
                      };

                      const headStyle: React.CSSProperties = {
                        background: '#f8fafc',
                          padding: '10px 12px',
                            fontWeight: 700,
                              color: '#003366',
                                fontSize: 14,
                                  borderBottom: '1px solid #ddd',
                                  };

                                  const bodyStyle: React.CSSProperties = {
                                    padding: 10,
                                    };

                                    const tableStyle: React.CSSProperties = {
                                      width: '100%',
                                        borderCollapse: 'collapse',
                                          fontSize: 12,
                                          };

                                          const thStyle: React.CSSProperties = {
                                            background: '#003366',
                                              color: 'white',
                                                padding: '8px 6px',
                                                  border: '1px solid #003366',
                                                    textAlign: 'center',
                                                    };

                                                    const tdStyle: React.CSSProperties = {
                                                      padding: '7px 6px',
                                                        border: '1px solid #ccc',
                                                          textAlign: 'center',
                                                          };

                                                          export const UtilitySummaryTables: React.FC<Props> = ({
                                                            results,
                                                              hasMarble,
                                                                electricalPts,
                                                                  plumbingPts,
                                                                    onElectricalChange,
                                                                      onPlumbingChange,
                                                                      }) => {
                                                                        // ✅ القيم المصححة (من الجداول المخصصة)
                                                                          const correctedPlasterWalls = Math.max(0, results.plasterWallsLabor - (results.intWindowArea + results.intDoorArea + results.extWindowArea + results.extDoorArea) - (results.tileKitchenWalls + results.tileBathroomWalls));
                                                                            const correctedPlasterCeiling = Math.max(0, results.plasterCeilingLabor - results.innerWallArea);
                                                                              const correctedPlasterArea = correctedPlasterWalls + correctedPlasterCeiling;
                                                                                const correctedPlasterCement = Math.ceil(correctedPlasterArea * 0.15);
                                                                                  const correctedPlasterSand = Math.ceil(correctedPlasterCement * 0.15);

                                                                                    const correctedTileFloor = Math.max(0, results.tileFloorArea - results.innerWallArea);
                                                                                      const correctedTileKitchenWalls = Math.max(0, results.tileKitchenWalls - 2);
                                                                                        const correctedTileBathroomWalls = Math.max(0, results.tileBathroomWalls - 2);
                                                                                          const correctedTileTotalArea = correctedTileFloor + results.tileKitchenFloor + results.tileBathroomFloor + correctedTileKitchenWalls + correctedTileBathroomWalls;
                                                                                            const correctedTileCement = Math.ceil(correctedTileTotalArea * 0.3);
                                                                                              const correctedTileSand = Math.ceil(correctedTileCement * 0.15);

                                                                                                const marbleArea = hasMarble ? Math.max(0, results.exteriorWallGross - results.extWindowArea - results.extDoorArea) : 0;
                                                                                                  const marbleCement = hasMarble ? Math.ceil(marbleArea * 0.3) : 0;
                                                                                                    const marbleSand = hasMarble ? Math.ceil(marbleCement * 0.07) : 0;
                                                                                                      const marbleAggregate = hasMarble ? Math.ceil(marbleCement * 0.075) : 0;

                                                                                                        // ✅ الإجماليات النهائية
                                                                                                          const totalBlocks = Math.ceil(results.exteriorBlocks + results.interiorBlocks);
                                                                                                            const totalCement = Math.ceil(results.exteriorBlockCement + results.interiorBlockCement + correctedPlasterCement + correctedTileCement + marbleCement);
                                                                                                              const totalSand = Math.ceil(results.exteriorBlockSand + results.interiorBlockSand + correctedPlasterSand + correctedTileSand + marbleSand);
                                                                                                                const totalAggregate = marbleAggregate;

                                                                                                                  // ✅ عدد الأبواب والنوافذ (منفصلة)
                                                                                                                    const totalDoors = results.doorGroups.reduce((s, g) => s + g.count, 0);
                                                                                                                      const totalWindows = results.windowGroups.reduce((s, g) => s + g.count, 0);

                                                                                                                        return (
                                                                                                                            <>
                                                                                                                                  {/* جدول الكهرباء والسباكة */}
                                                                                                                                        <div style={cardStyle}>
                                                                                                                                                <div style={headStyle}>💡🔌 الكهرباء والسباكة</div>
                                                                                                                                                        <div style={bodyStyle}>
                                                                                                                                                                  <table style={tableStyle}>
                                                                                                                                                                              <thead>
                                                                                                                                                                                            <tr>
                                                                                                                                                                                                            <th style={thStyle}>البند</th>
                                                                                                                                                                                                                            <th style={thStyle}>عدد النقاط</th>
                                                                                                                                                                                                                                          </tr>
                                                                                                                                                                                                                                                      </thead>
                                                                                                                                                                                                                                                                  <tbody>
                                                                                                                                                                                                                                                                                <tr>
                                                                                                                                                                                                                                                                                                <td style={tdStyle}>السباكة</td>
                                                                                                                                                                                                                                                                                                                <td style={tdStyle}>
                                                                                                                                                                                                                                                                                                                                  <input
                                                                                                                                                                                                                                                                                                                                                      type="number"
                                                                                                                                                                                                                                                                                                                                                                          min="0"
                                                                                                                                                                                                                                                                                                                                                                                              value={plumbingPts}
                                                                                                                                                                                                                                                                                                                                                                                                                  onChange={e => onPlumbingChange(Number(e.target.value))}
                                                                                                                                                                                                                                                                                                                                                                                                                                      style={{ width: 70, textAlign: 'center', padding: 4, border: '1px solid #ccc', borderRadius: 4 }}
                                                                                                                                                                                                                                                                                                                                                                                                                                                          onFocus={(e) => e.target.select()}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                            />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            </td>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          </tr>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <tr>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <td style={tdStyle}>الكهرباء</td>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <td style={tdStyle}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <input
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              type="number"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  min="0"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      value={electricalPts}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          onChange={e => onElectricalChange(Number(e.target.value))}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              style={{ width: 70, textAlign: 'center', padding: 4, border: '1px solid #ccc', borderRadius: 4 }}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  onFocus={(e) => e.target.select()}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </td>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  </tr>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              </tbody>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </table>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      </div>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            {/* جدول إجمالي الكميات النهائي */}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <div style={cardStyle}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <div style={headStyle}>📦 إجمالي الكميات النهائي</div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <div style={bodyStyle}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <table style={tableStyle}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <thead>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <tr>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <th style={thStyle}>البند</th>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <th style={thStyle}>الكمية</th>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <th style={thStyle}>الوحدة</th>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </tr>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </thead>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <tbody>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <tr>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <td style={tdStyle}>إجمالي البلوك</td>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <td style={tdStyle}>{totalBlocks}</td>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <td style={tdStyle}>بلوكة</td>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </tr>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <tr>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <td style={tdStyle}>إجمالي البلاط</td>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <td style={tdStyle}>{Math.ceil(correctedTileTotalArea)}</td>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <td style={tdStyle}>م²</td>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </tr>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <tr>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <td style={tdStyle}>إجمالي الأسمنت</td>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <td style={tdStyle}>{totalCement}</td>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <td style={tdStyle}>كيس</td>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </tr>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <tr>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <td style={tdStyle}>إجمالي الرمل</td>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <td style={tdStyle}>{totalSand}</td>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <td style={tdStyle}>م³</td>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            </tr>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <tr>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <td style={tdStyle}>إجمالي الركام</td>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <td style={tdStyle}>{totalAggregate}</td>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <td style={tdStyle}>م³</td>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </tr>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      {hasMarble && (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <tr>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <td style={tdStyle}>إجمالي الرخام</td>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <td style={tdStyle}>{Math.ceil(marbleArea)}</td>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <td style={tdStyle}>م²</td>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            </tr>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          )}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        {/* ✅ فصل الأبواب والنوافذ */}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <tr>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <td style={tdStyle}>إجمالي الأبواب</td>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <td style={tdStyle}>{totalDoors}</td>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <td style={tdStyle}>باب</td>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </tr>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <tr>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <td style={tdStyle}>إجمالي النوافذ</td>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <td style={tdStyle}>{totalWindows}</td>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <td style={tdStyle}>نافذة</td>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </tr>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            </tbody>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      </table>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          };